function towerCreateBattle(room,team,catalog,random=Math.random){if(!Number.isInteger(room)||room<1||!team.length||team.length>3||!catalog.length)throw Error('Équipe ou chambre invalide.');const pool=catalog.filter(c=>towerStats[c.rarity]&&!['Exclusive','Transcendant'].includes(c.rarity)),ranks=room<6?['Commun','Rare','Épique']:room<16?['Rare','Épique','Légendaire']:['Épique','Légendaire','Mythique','Secret'];const allowed=pool.filter(c=>ranks.includes(c.rarity)),p=allowed.length?allowed:pool;if(!p.length)throw Error('Catalogue indisponible.');const fixed=towerRoomStats(room),n=3,enemies=[];for(let i=0;i<n;i++){const e=towerUnit(p[Math.min(p.length-1,Math.floor(random()*p.length))],1,true);e.maxHp=e.hp=fixed.hp;e.attack=fixed.attack;enemies.push(e);}return {room,players:team.map(c=>towerUnit(c)),enemies,turn:1,alt:1,result:null,log:['Chambre '+room+' : le combat commence.']};}

