function chooseCombatAITarget(team,battle,random=Math.random){const alive=team.filter(u=>u.hp>0),taunt=alive.find(u=>u.shieldTurns>0)||alive.find(u=>u.moonTaunt);if(taunt)return taunt;if(!alive.length)return null;const pool=alive.length>1?alive.filter(u=>team.indexOf(u)!==battle.aiLastTarget):alive;const target=pool[Math.min(pool.length-1,Math.floor(random()*pool.length))];battle.aiLastTarget=team.indexOf(target);return target;}

function releaseLastBanished(enemies){if(!enemies.some(e=>e.hp>0)||enemies.some(e=>e.hp>0&&!e.banished))return false; for(const e of enemies)delete e.banished;return true;}

function combatSpentSpecial(unit,card=unit){if(!unit||unit.shadowName||unit.summon)return '';if(unit.sealed)return 'sealed';const name=String(card?.name||unit.name||'').toLowerCase().replace(/[^a-z]/g,'');if(unit.ariseUsed&&/^s(?:u|o)n?g?jinwoo$/.test(name))return 'arise';if(unit.rikaUsed&&/^(okkotsu)?yuu?ta(okkotsu)?$/.test(name))return 'rika';if(unit.atomicUsed&&name==='cidkagenou')return 'atomic';if(unit.voidUsed&&/gojou?/.test(name))return 'infinityvoid';if(unit.legendUsed&&/^broly/.test(name))return 'legendary';if(unit.hakiUsed&&ROGER_NAME.test(name))return 'haki';if(unit.vampiric&&name==='alucard')return 'vampiric';if((unit.titan||unit.titanUsed)&&/^eren/.test(name))return 'titan';if(unit.muiUsed&&/^go[kc]uu?(son)?mui|^songo[kc]uu?mui/.test(name))return 'mui';if(unit.futureUsed&&/^shinra(kusakabe)?$/.test(name))return 'future';if(unit.mugetsuUsed&&/^ichigo(kurosaki)?mugetsu$/.test(name))return 'mugetsu';if(unit.heavenUsed&&isPucciHeavenName(unit,card))return 'heaven';if(unit.genjutsuUsed&&isItachiGenjutsuName(unit,card))return 'genjutsu';if(unit.neantUsed&&isZenoName(unit,card))return 'neant';if(unit.arsenal&&(unit.tojiSwap===true||![0,1,2].includes(unit.tojiLast))&&/^toji(fushiguro|zenin)?$/.test(name))return 'arsenal';if(unit.overlordUsed&&/^(ainz|ainzooalgown|momonga)$/.test(name))return 'overlord';if(unit.berserk&&/^guts$/.test(name))return 'berserk';if(unit.almightyUsed&&/^(yhwach|yhwatch|juhabach)/.test(name))return 'almighty';if(unit.eaUsed&&/^gilgamesh/.test(name))return 'enuma';if(unit.geass===true&&/^lelouch/.test(name))return 'geass';if(unit.akazaUsed&&name==='akaza')return 'akaza';if(unit.rinneganUsed&&/^madara/.test(name))return 'rinnegan';if(unit.timeStopUsed&&/^(julius(novachrono)?|diobrando[a-z]*)$/.test(name))return /^dio/.test(name)?'zawarudo':'timestop';return '';}

