function summonAriseShadows(players,actor){const targets=[];let n=0;for(const unit of players){if(unit===actor||unit.summon)continue;unit.shadowName=['Igris','Beru'][n++]; for(const k of ['geass','empowered','rinneganTurns','rinneganFresh','dodges','shieldTurns','frozen','frozenFresh','frozenWorld','frozenVoid','frozenHaki','frozenIce','frozenGeass','frozenDoor','banished','intimidated','galaxyTired','brolyStacks','almighty','vampiric','titan','fireArmor','fireStore','alter','alterUsed','huntUsed','book','sealed','mui','muiFresh','muiUsed','futureUsed','mugetsuUsed','heavenUsed','genjutsuUsed','neantUsed','janembaDodges','janembaDodgeUsed','blackHole','frierenWardUsed','arsenal','tojiLast','tojiSwap','tojiSpent','overlordUsed','overlordGuard','overlordRose','xebecWard','xebecFresh','xebecBlocked','berserk','gutsRage','bleed','bleedDamage','bleedFresh','burn','fullPower'])delete unit[k]; unit.maxHp=actor.maxHp;unit.hp=Math.max(1,Math.round(actor.maxHp*.5));unit.attack=actor.attack;unit.cooldown=0;unit.guarding=false;targets.push(players.indexOf(unit));if(n===2)break;}actor.ariseUsed=true;actor.cooldown=0;return targets;}

