function summonRika(players,actor){actor.rikaUsed=true;actor.cooldown=0;players.push({...(Number.isInteger(actor.cardId)?{cardId:RIKA_CARD_ID}:{key:'summon:rika'}),name:'Rika',image:rikaImage,rarity:'Mythique',summon:'Rika',summonTurns:3, maxHp:Math.max(1,Math.round(actor.maxHp*.7)),hp:Math.max(1,Math.round(actor.maxHp*.7)),attack:Math.max(1,Math.round(actor.attack*.7)),cooldown:0,acted:true,guarding:false});return players.length-1;}

