function storyEndHTML(b){if(b.mode==='hw26'&&typeof hw26EndHTML==='function')return hw26EndHTML(b);if(b.mode==='gboss'&&typeof gbossEndHTML==='function')return gbossEndHTML(b);if(b.mode==='event')return halloweenEndHTML(b);if(b.mode==='rogue'&&typeof rogueEndHTML==='function')return rogueEndHTML(b);if(b.mode==='farm')return farmEndHTML(b);
 const won=b.result==='won',isRaid=b.mode==='raid',next=nextBattleLevel(b),survivors=b.players.filter(u=>u.hp>0),stars=won?Math.max(1,Math.round(survivors.length/b.players.length*3)):0,level=battleLevel(b);
 return `<section class="story-end-screen ${won?'won':'lost'}" aria-labelledby="storyResultTitle"><div class="story-result-rays" aria-hidden="true"></div><div class="story-end-panel"><button type="button" class="story-result-close" data-story-map aria-label="Fermer le résultat et revenir à mon équipe">×</button><div class="story-result-trophy" aria-hidden="true">${storyResultEmblem(won)}</div><h2 id="storyResultTitle" tabindex="-1">${won?'VICTOIRE':'DÉFAITE'}</h2><p class="combat-result-message">${won?'Belle victoire. Ton équipe a fait la différence.':'Chaque défaite prépare la prochaine victoire.'}</p><span class="story-result-chapter">${escapeHTML(combatSeriesLabel(level))} · ${b.mode==='raid'?'RAID':'ACTE'} ${level.act}</span><p class="story-result-level">${escapeHTML(level.title)}</p><div class="story-result-stars" role="img" aria-label="${stars} étoile${stars>1?'s':''} sur 3, selon les cartes encore en vie">${[1,2,3].map(n=>`<span class="${n<=stars?'lit':''}" aria-hidden="true">★</span>`).join('')}</div><div class="story-result-team">${b.players.map(u=>{const c=ariseShadowCard(u,cardById(u.cardId),cards);return c?`<figure class="${u.hp?'':'is-ko'}"><div style="--r:${c.color};--result-rim:${typeof cardRarityPaint==='function'?cardRarityPaint(c.rarity):c.color}"><img src="${escapeHTML(c.image)}" alt="" draggable="false">${u.hp?'':'<span>K.O.</span>'}</div><figcaption>${escapeHTML(c.name)}</figcaption></figure>`:'';}).join('')}</div><div class="story-result-numbers"><div><strong>${survivors.length}/${b.players.length}</strong><span>cartes debout</span></div><div><strong>${Math.max(1,b.turn-1)}</strong><span>tours</span></div><div><strong>${isRaid?state.story.raidWins:state.story.wins}</strong><span>victoire${(isRaid?state.story.raidWins:state.story.wins)>1?'s':''} ${isRaid?'Raid':'Story'}</span></div></div><div class="story-result-progress"><span aria-hidden="true">${won?'✦':'↻'}</span><div><strong>${won?(isRaid?'Raid remporté !':!next?'Story terminée !':level.act===storyWorldActCount(level.worldId)?'Monde terminé !':'Acte accompli !'):'Ce n’est que partie remise.'}</strong><small>${won?isRaid?state.story.raidCleared.length+' / '+raidLevels.length+' raids remportés':storyVisibleCleared().length+' / '+storyLevels.length+' actes terminés':'Modifie ton équipe ou tente une autre stratégie.'}</small></div></div>${b.reward?.ki>0?`<div class="story-first-reward"><span>✦ PREMIÈRE VICTOIRE</span><span class="ki-text" aria-hidden="true">KI</span><strong>+${b.reward.ki.toLocaleString('fr-FR')} <small>ki</small></strong><p>Récompense ajoutée à ton portefeuille.</p></div>`:won?'<p class="story-reward-note">Les récompenses de première victoire se reçoivent une seule fois.</p>':''}${typeof evolutionLootHTML==='function'?evolutionLootHTML(b):''}<div class="story-result-buttons"><button type="button" class="btn primary" ${isRaid?'data-raid-level':'data-story-level'}="${b.level}">↻ Rejouer</button><button type="button" class="btn ghost" ${won&&next?(isRaid?'data-raid-level':'data-story-level')+'="'+next.id+'"':'disabled'}>Suivant →</button><button type="button" class="btn ghost" data-story-map>Retour aux actes</button></div><small class="story-result-note">Tes cartes sont conservées et récupèrent tous leurs PV au prochain combat.</small></div></section>`;
}

