function fit(){
  if(!nav||mobile.matches)return;
  const list=items();
  if(fitMemo&&typeof ResizeObserver==='function'){const sig=fitSig(list);
   if(sig===fitMemo.sig&&list.length===fitMemo.n&&list.every(b=>b.classList.contains('tn-fold')===fitMemo.fold.has(b))){
    const info=fitMemo.shown.map(x=>({...x,active:x.b.classList.contains('active')}));const plan=foldPlan(info,fitMemo.avail);
    if(plan.size===fitMemo.plan.size&&[...plan].every(i=>fitMemo.plan.has(i))){fitState(list.filter(b=>fitMemo.folded.has(b)));return;}}}
  for(const b of list)b.classList.toggle('tn-fold',b.hasAttribute('data-tn-secondary'));
  const avail=nav.clientWidth;const gap=parseFloat(getComputedStyle(nav).columnGap)||0;
  const shownEls=list.filter(b=>!b.classList.contains('tn-fold')&&getComputedStyle(b).display!=='none');
  
  const info=shownEls.map(b=>({b,view:b.dataset.view,w:b.offsetWidth+gap,event:b.hasAttribute('data-tn-event'),active:b.classList.contains('active')}));
  const plan=foldPlan(info,avail);for(const i of plan)info[i].b.classList.add('tn-fold');
  
  
  const sec=list.filter(b=>b.hasAttribute('data-tn-secondary'));for(const b of sec)b.classList.remove('tn-fold');const secShown=new Set(sec.filter(b=>getComputedStyle(b).display!=='none'));for(const b of sec)b.classList.add('tn-fold');
  const folded=list.filter(b=>b.classList.contains('tn-fold')&&(secShown.has(b)||shownEls.includes(b)));
  fitMemo={sig:fitSig(list),n:list.length,avail,shown:info.map(({b,view,w,event})=>({b,view,w,event})),plan,folded:new Set(folded),fold:new Set(list.filter(b=>b.classList.contains('tn-fold')))};
  fitState(folded);
 }

