 if(Array.isArray(g._rp)){const f=g._rp,pulls=[];let last=0;for(let i=0;i+2<f.length;i+=3){last+=f[i+1];pulls.push({id:f[i],at:last,rarity:yuroSaveRarities[f[i+2]]});}g.recentPulls=pulls;delete g._rp;}
