function rebuildRaidWorlds(config=[]){raidWorlds.splice(0,raidWorlds.length,...raidWorldDefaults.map(w=>({...w})));raidLevels.splice(0,raidLevels.length,...raidLevelDefaults.map(l=>({...l})));for(const world of config){const at=raidWorlds.findIndex(w=>w.id===world.id);if(at>=0)raidWorlds[at]={...world};else raidWorlds.push({...world});const prior=raidLevels.filter(l=>l.raidWorld===world.id),first=raidLevels.findIndex(l=>l.raidWorld===world.id),levels=world.acts.map((a,i)=>{const old=prior.find(l=>l.id===a.id);return {...old,id:a.id,title:a.title,series:old?.series||world.series,color:world.color,act:i+1,worldId:0,raidWorld:world.id,mode:'raid',enemies:a.enemies,manual:a.manual===true,hp:a.enemies[0]?.hp||old?.hp||200,attack:a.enemies[0]?.attack||old?.attack||35};});for(let i=raidLevels.length-1;i>=0;i--)if(raidLevels[i].raidWorld===world.id)raidLevels.splice(i,1);raidLevels.splice(first<0?raidLevels.length:first,0,...levels);}if(config.length){const order=new Map(config.map((w,i)=>[w.id,i])),base=raidWorlds.map(w=>w.id),rank=id=>order.has(id)?order.get(id):1000+base.indexOf(id);raidWorlds.sort((a,b)=>rank(a.id)-rank(b.id));raidLevels.sort((a,b)=>rank(a.raidWorld)-rank(b.raidWorld)||a.act-b.act);}}

