function yf3Wing(g1,g2,edge,{n=11,L=46,w=7.5,arm=[34,-40]}={}){let s='';const f=v=>v.toFixed(1);
 
 const B=t=>[2*t*(1-t)*10+t*t*arm[0],2*t*(1-t)*(-34)+t*t*arm[1]];
 const feather=(x,y,a,len,ww,g)=>'<g transform="translate('+f(x)+','+f(y)+') rotate('+f(a)+')"><path d="M0,'+f(-ww*.45)+'C'+f(len*.3)+','+f(-ww*1.05)+' '+f(len*.78)+','+f(-ww*.9)+' '+f(len)+',0C'+f(len*.8)+','+f(ww*.62)+' '+f(len*.32)+','+f(ww*.8)+' 0,'+f(ww*.45)+'Z" fill="url(#'+g+')" stroke="'+edge+'" stroke-width=".7"/><path d="M2,0L'+f(len*.88)+',0" stroke="'+edge+'" stroke-width=".5" stroke-opacity=".55"/></g>';
 for(let i=n-1;i>=0;i--){const t=i/(n-1),[x,y]=B(t*.96);s+=feather(x,y,78-t*122,L*(.36+.64*Math.pow(t,.75)),w*(.85+.35*t),g1);}
 const m=n-2;for(let i=m-1;i>=0;i--){const t=i/(m-1),[x,y]=B(t*.9);s+=feather(x,y,62-t*104,L*(.2+.26*t),w*1.05,g2);}
 const [wx,wy]=B(1);return s+'<path d="M-4,6C-2,-14 8,-30 '+f(wx)+','+f(wy)+'C'+f(wx-10)+','+f(wy+16)+' 12,-6 6,10Z" fill="url(#'+g2+')" stroke="'+edge+'" stroke-width=".7"/>';}

