function applyServerPull(data){
 if(data.transcendentEditions)state.transcendentEditions=data.transcendentEditions;
 if(Number.isSafeInteger(data.referralBoosters))state.referralBoosters=data.referralBoosters;
 if(Number.isSafeInteger(data.questBoosters))state.questBoosters=data.questBoosters; if(data.prestige&&typeof data.prestige==='object')state.prestige=data.prestige;if(data.prestigeCards&&typeof data.prestigeCards==='object')state.prestigeCards=data.prestigeCards;state.ki=data.ki;state.freeBoosters=data.freeBoosters;state.freeBoosterAt=data.freeBoosterAt;
 for(const [id,n] of Object.entries(data.qty||{}))state.qty[Number(id)]=n;
 
 if(typeof authorityReplayPending==='function'){const fromServer=new Set(Object.keys(data.qty||{}).map(Number));authorityReplayPending(id=>fromServer.has(id));}
 cloudSaveState.revision=data.revision;cloudSaveState.updatedAt=data.updatedAt;
 try{cloudSaveState.fingerprint=JSON.stringify(cloudSnapshot());}catch{}
}

function castTimeStop(enemies,actor,world=false){const targets=[],guarded=[];let back=false;enemies.forEach((e,i)=>{if(e.hp>0){const gc=guardControl(e,actor);if(gc){if(gc==='reflected')back=true;else if(gc!=='blocked')guarded.push({index:i,result:gc});return;}e.frozen=1; if(e.struck)Object.assign(e,{frozenFresh:true});else delete e.frozenFresh;if(world)e.frozenWorld=true;else delete e.frozenWorld;delete e.frozenStun;delete e.frozenControl;delete e.frozenHaki;delete e.frozenVoid;delete e.frozenIce;delete e.frozenGeass;delete e.frozenDoor;delete e.banished;targets.push(i);}});actor.timeStopCasts=(Number(actor.timeStopCasts)||0)+1;if(actor.timeStopCasts>=STUN_SKILL_USES)actor.timeStopUsed=true;actor.cooldown=actor.timeStopUsed?0:STUN_SKILL_RECHARGE;if(back){actor.frozen=1;if(world)actor.frozenWorld=true;else delete actor.frozenWorld;delete actor.frozenStun;delete actor.frozenControl;delete actor.frozenHaki;}targets.guarded=guarded;return targets;}

function prime(s,early,noDeck){if(s.primed)return !!s.card;s.primed=true;const d=dlg();if(!d?.open)return false;
  if(early)hideReview(true);
  if(d.classList.contains('staged')){__R.getElementById('packStage')?.classList.add('hidden');d.classList.remove('staged','tearing');}
  priming=true;try{baseBegin();}catch(err){console.warn('pack-sachet',err);}finally{priming=false;}
  const f=flow();if(f)f.busy=true;
  const card=d.querySelector('#packCards .reveal-card');
  if(early&&s.state==='idle'&&!s.el.contains(document.activeElement))s.pack.focus({preventScroll:true});
  if(!card)return false;
  s.card=card;card.style.setProperty('animation','none','important');card.style.visibility='hidden';card.classList.add('po5-landing');
  if(card.classList.contains('revealed')){const inner=card.querySelector('.reveal-inner');s.flip=true;if(inner)inner.style.transition='none';card.classList.remove('revealed');}
  if(!noDeck)buildDeck(s);return true;}

