function lot(){const all=list();if(memo&&memo.n===all.length)return memo;
  const fresh=all.filter(c=>c&&c.id>=LOT_FIRST_ID&&c.image&&!c.adminArchived&&!(typeof isRetiredCatalogCard==='function'&&isRetiredCatalogCard(c)));
  const before=new Set(all.filter(c=>c&&c.id<LOT_FIRST_ID).map(c=>c.series));
  const bySeries=new Map();for(const c of fresh){if(before.has(c.series))continue;if(!bySeries.has(c.series))bySeries.set(c.series,[]);bySeries.get(c.series).push(c);}
  const best=[...fresh].sort((a,b)=>(RANK[a.rarity]??9)-(RANK[b.rarity]??9)||(b.popularity||0)-(a.popularity||0));
  const anime=[...bySeries.entries()].map(([name,l])=>({name,n:l.length,cover:l[0].seriesImage,pop:Math.max(...l.map(c=>c.popularity||0))})).sort((a,b)=>b.pop-a.pop);
  return memo={n:all.length,fresh,best,anime,existing:new Set(fresh.filter(c=>before.has(c.series)).map(c=>c.series)).size};}

