function castRage(target,actor){actor.cooldown=2;if(target&&target.hp>0&&xebecBlock(target))return {hits:[],damage:0,blocked:true};if(target?.berserk&&target.hp>0)gutsRageUp(target);const m=(target?.shieldTurns>0?.5:target?.moonTaunt&&target.hp>0?.7:1)*(target?.titan?.85:1)*(target?.markTurns>0?1.3:1)*(target?.geass!==true&&frierenWardSpend(target)?FRIEREN_WARD_CUT:1);if(target?.fireArmor>0)armorBurn(target,actor);const per=Math.max(1,Math.round(actor.attack*.22*attackMultiplier(actor)*m));const hits=[];for(let i=0;i<8&&target&&target.hp>0;i++){const raw=target?.fireArmor>0?absorbFire(target,per):per;const d=Math.min(target.hp,raw);target.hp-=d;hits.push(d);}if(hits.length)brolyHit(target);almightyRevive(target);return {hits,damage:hits.reduce((n,d)=>n+d,0)};}

