function price(card,at,preview=false){if(card.catalogKey==='infinity-black-freezer'||card.key==='key:infinity-black-freezer')return 300000;
  const n=seed(card.key),phase=n/4294967296*Math.PI*2;
  const t=at/(preview?120000:3600000),base=typeof cardMarketBounds==='function'?cardMarketBounds(card).recommended:bases[card.rarity]||10;
  const wave=.19*Math.sin(t/(9+n%13)+phase)+.12*Math.sin(t/(37+n%47)+phase*2)+.06*Math.sin(t/(2+n%5)+phase*3);
  const value=Math.max(1,Math.round(base*(typeof cardMarketBounds==='function'?1:1.65+(n%31)/100)*(1+wave)));
  
  if(typeof cardMarketBounds==='function'){const b=cardMarketBounds(card);return Math.max(b.min,Math.min(b.max,value));}
  return value;
 }

