function cardReflectionHTML(c){return `<span class="yuro-card-material" data-material-rarity="${escapeHTML(c.rarity)}" aria-hidden="true"><span class="yuro-material-shine"></span><span class="yuro-material-relief"></span><span class="yuro-material-glare"></span></span>`;}

function raidCanStart(id){const level=raidLevels.find(l=>l.id===id);if(!level)return false;if(state.story.raidCleared.includes(id))return true;return raidLevels.filter(l=>l.raidWorld===level.raidWorld&&l.act<level.act).every(l=>state.story.raidCleared.includes(l.id));}

function sig(d){return JSON.stringify([d.duo.length,d.rew.length,d.farm&&d.farm.stats,d.worlds.map(w=>w.id+(w.on?'*':'')+(w.locked?'L':'')+w.prog),d.acts.map(a=>a.id+(a.on?'*':'')+(a.locked?'L':'')+a.state),d.title,d.status,d.slots.map(s=>s.name),d.power,d.hp,d.go]);}

function castInfinityVoid(actor){actor.voidUsed=true;actor.cooldown=3;const hp=Math.round(actor.maxHp*.3),before=actor.attack;actor.maxHp+=hp;actor.hp=Math.min(actor.maxHp,actor.hp+hp);actor.attack=Math.round(actor.attack*1.3);return {hp,attack:actor.attack-before};}

function castLegendary(actor){actor.legendUsed=true;actor.cooldown=1;const hp=Math.round(actor.maxHp*.2),before=actor.attack;actor.maxHp+=hp;actor.hp=Math.min(actor.maxHp,actor.hp+hp);actor.attack=Math.round(actor.attack*1.2);return {hp,attack:actor.attack-before};}

function series(card,days,at=Date.now(),preview=false){
  const end=Math.floor(at/60000)*60000,span=Math.max(1,Math.min(90,days))*86400000;
  return Array.from({length:97},(_,i)=>{const time=end-span+span*i/96;return {at:time,value:price(card,time,preview)};});
 }

function yuroSaveSeed(c){if(typeof releasedCatalog==='undefined'||!Array.isArray(releasedCatalog))return null;if(!yuroSaveSeedIndex)yuroSaveSeedIndex=new Map(releasedCatalog.map(x=>[yuroSaveSeedKey(x),x]));return yuroSaveSeedIndex.get(yuroSaveSeedKey(c))||null;}

function yf3Rad(id,stops,r=100){return '<radialGradient id="'+id+'" cx="0" cy="0" r="'+r+'" gradientUnits="userSpaceOnUse">'+stops.map(([o,c,a])=>'<stop offset="'+o+'" stop-color="'+c+'"'+(a!=null?' stop-opacity="'+a+'"':'')+'/>').join('')+'</radialGradient>';}

function upgradeCostPerStar(card){if(card?.rarity!=='Secret')return 2;const key=upgradeCardKey(card);const rules=typeof combatEvolutionRules==='function'?combatEvolutionRules():state.evolution?.settings?.evolutions||[];return rules.some(r=>r.to===key)?2:1;}

function cardDetailVideoHTML(c){return validCardVideo(c.videoUrl)?'<video class="card-detail-video" data-card-video autoplay muted loop playsinline preload="metadata" poster="'+escapeHTML(c.image)+'"><source src="'+escapeHTML(c.videoUrl)+'"></video>':'';}

function averageRarityRates(packId='multivers'){const pack=getBoosterDefinition(packId),rates=pack?rarityRates(boosterPool(packId),pack.weights):[];return Object.keys(rarityColors).map(r=>({rarity:r,chance:rates.find(rate=>rate.rarity===r)?.chance||0}));}

function serverCardIdentity(c){if(c?.catalogKey)return 'key:'+c.catalogKey;const series=String(c?.series||'').trim();return Number.isInteger(c?.anilistCharacterId)?'anilist:'+c.anilistCharacterId+'|'+series:'name:'+String(c?.name||'').trim()+'|'+series;}

function pullAge(timestamp){const minutes=Math.max(0,Math.floor((Date.now()-timestamp)/60000));return minutes<1?'À l’instant':minutes<60?`Il y a ${minutes} min`:minutes<1440?`Il y a ${Math.floor(minutes/60)} h`:`Il y a ${Math.floor(minutes/1440)} j`;}

function kind(b){return b.hasAttribute('data-tutorial-resume')?'guide':b.dataset.view==='friends'?'friends':b.dataset.view==='ranking'?'ranking':b.id==='duelInbox'?'duel':b.dataset.view==='quests'?'quests':b.dataset.view==='cagnotte'?'cagnotte':'';}

function combatAutoButtonHTML(kind,on,label,title){return `<button type="button" class="btn ghost small combat-auto-btn ${on?'is-on':''}" data-combat-auto="${kind}" aria-pressed="${on}" title="${title}">${label}<em>${on?'ON':'OFF'}</em></button>`;}

function kiShort(v){const n=Math.max(0,Math.floor(Number(v)||0));if(n<10000)return n.toLocaleString('fr-FR');if(n<1000000)return Math.floor(n/1000)+'k';const m=Math.floor(n/100000)/10;return m.toLocaleString('fr-FR',{maximumFractionDigits:1})+'M';}

function sortedUniverseNames(){const names=[...series].map(s=>s.name),key=names.join('\u0001');if(sortedUniverseMemo.key!==key)sortedUniverseMemo={key,list:names.slice().sort((a,b)=>a.localeCompare(b,'fr'))};return sortedUniverseMemo.list.slice();}

function storyDelay(baseMs,callback){clearTimeout(storyAnimationTimer);const duration=Math.max(0,baseMs/storySpeed);storyPending={deadline:Date.now()+duration,callback};storyAnimationTimer=setTimeout(()=>{storyPending=null;callback();},duration);}

function storyWorldOpen(id){return Number.isInteger(id)&&storyWorlds.some(w=>w.id===id)&&(storyLevels.some(l=>l.worldId===id&&state.story.cleared.includes(l.id))||storyLevels.filter(l=>l.worldId<id).every(l=>state.story.cleared.includes(l.id)));}

function download(blob){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='yuro-tirage.png';a.hidden=true;(dlg()||document.body).append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),5000);}

function recordPersonalPulls(pulled,now=Date.now()){state.recentPulls=normalizeRecentPulls(state.recentPulls,now);for(const c of pulled)state.recentPulls.push({id:c.id,at:now,rarity:c.rarity});state.recentPulls=state.recentPulls.slice(-10000);}

function combatAutoKind(b){if(!b||b.mode==='event')return '';if(b.mode==='farm')return 'farm';if(!b.mode&&typeof storyMode!=='undefined'&&storyMode==='infinity')return 'castle';return ['story','raid',undefined].includes(b.mode)?'campaign':'';}

function tutorialTrack(id){const t=tutorialData();if(!t||t.status==='done'||!tutorialStepIds.includes(id)||t.completed.includes(id))return;state.playerProgress.tutorial={...t,completed:[...t.completed,id]};tutorialReview=null;queueTutorial();}

function yf3Rays(u,n,r0,r1,c,w=2.4){let s='';for(let i=0;i<n;i++){const a=i*360/n,l=i%2?r1:r1*.84;s+='<path d="M'+yf3Pt(r0,a-w)+'L'+yf3Pt(l,a)+'L'+yf3Pt(r0,a+w)+'Z" fill="url(#'+u+'r)"/>';}return [yf3Rad(u+'r',[[r0/r1,c,.85],[1,c,0]],r1),s];}

function sortedAnimeIndexes(list){const counts=new Map();for(const c of cards)counts.set(c.series,(counts.get(c.series)||0)+1);return [...list].sort((a,b)=>(counts.get(b.name)||0)-(counts.get(a.name)||0)||a.name.localeCompare(b.name,'fr'));}

function combatSeriesLabel(level){if(level?.mode==='raid'||level?.raidWorld&&level.raidWorld!==0){const w=typeof raidWorlds!=='undefined'&&raidWorlds.find(x=>x.id===level.raidWorld);if(w?.series)return w.series;}return level?.series||'';}

function label(b){
  if(b.matches('[data-story-map],[data-infinity-lobby]'))return 'RETOUR';
  if(/rejouer/i.test(b.textContent))return 'NOUVEL ESSAI';
  if(/suivant/i.test(b.textContent))return 'COMBAT SUIVANT';
  return 'AU COMBAT';
 }

function focusBoosterCheckout(){const title=$('purchaseTitle');title?.setAttribute('tabindex','-1');title?.focus({preventScroll:true});$('boosterPurchase')?.scrollIntoView({behavior:reducedMotion()?'auto':'smooth',block:'nearest'});}

function setupCandy(){const c=__R.getElementById('hw26TopCandy');if(!c)return false;
  if(!c.classList.contains('wv3'))c.classList.add('wv3','wv3-candy');
  watch(c,'candy',()=>parse(c.getAttribute('aria-label')));return true;}

function updateQuestCountdown(){const node=$('questCountdown');if(!node)return;const left=Math.ceil((1800000-Date.now()%1800000)/1000);node.textContent='Renouvellement dans '+Math.floor(left/60)+':'+String(left%60).padStart(2,'0');}

function yuroLocalDecode(value){if(!value||typeof value!=='object'||value.yuroLocal!==1||!value.game)return value;try{const p=yuroExpandSave({compact:1,game:structuredClone(value.game)});return p.game;}catch{return value.game;}}

function applyInfinitySnapshot(snapshot){infinityUI.loadedAt=Date.now();infinityUI.data=snapshot;if(typeof infinityRestorePending==='function')infinityRestorePending();if(snapshot?.me?.battle?.result)infinityUI.showLobby=true;}

function storyWorldCards(worldId){const world=storyWorlds.find(w=>w.id===worldId);return world?combatEnemyCatalog().filter(c=>c.series===world.series).sort((a,b)=>combatCardIdentity(a).localeCompare(combatCardIdentity(b))):[];}

function upgradeCardKey(card){return card.catalogKey?'key:'+card.catalogKey:Number.isInteger(card.anilistCharacterId)?'anilist:'+card.anilistCharacterId+'|'+card.series:'name:'+String(card.name).toLowerCase()+'|'+card.series;}

function cancelPackScene(){__R.querySelectorAll('.pack-fortune').forEach(n=>n.remove());packSceneVersion++;clearTimeout(packSceneTimer);packSceneTimer=null;if(typeof cancelPackReview==='function')cancelPackReview();}

function campaignFingerprint(value){const text=JSON.stringify(value);let hash=2166136261;for(let i=0;i<text.length;i++)hash=Math.imul(hash^text.charCodeAt(i),16777619);return (hash>>>0).toString(16)+':'+text.length;}

function pool(){const fav=(state.favorites||[]).map(id=>typeof cardById==='function'?cardById(id):null).filter(owns);if(fav.length)return fav;return ownedCards().sort((a,b)=>tier(b)-tier(a)||a.id-b.id).slice(0,12);}

function activeBooster(){if(view==='halloween')return getBoosterDefinition('halloween');return getBoosterDefinition(selectedBoosterId==='halloween'?'multivers':selectedBoosterId)||getBoosterDefinition('multivers');}

function yf3Flame(b,h,g){return '<path d="M'+(-b)+',0C'+(-b)+','+(-h*.45)+' '+(-b*.15)+','+(-h*.55)+' 0,'+(-h)+'C'+(b*.15)+','+(-h*.55)+' '+b+','+(-h*.45)+' '+b+',0Q0,'+(b*.6)+' '+(-b)+',0Z" fill="url(#'+g+')"/>';}

function combatEnemyById(id){return cardById(id)||(state.story?.enemyCards||[]).find(c=>c.id===id)|| (typeof allCards!=='undefined'&&allCards[id]&&!allCards[id].retired&&allCards[id].name?allCards[id]:undefined);}

function sfx(){try{if(typeof state!=='undefined'&&state.sound===false)return;audio=audio||new Audio('https://yurocollection.fr/assets/majin-vegeta-explosion-v4.mp3');const a=audio.cloneNode();a.volume=.5;a.play().catch(()=>{});}catch{}}

function seriesProgress(s){const all=cards.filter(c=>c.series===s.name);const owned=all.filter(c=>state.qty[c.id]>0).length;return {total:all.length,owned,percent:all.length?Math.round(owned/all.length*100):0}}

function yf3P(kind,list){return list.map(([x,y,dx,dy,t,d,s])=>'<i class="yf3-p '+kind+'" aria-hidden="true" style="--x:'+x+';--y:'+y+';--dx:'+dx+';--dy:'+dy+';--t:'+t+'s;--d:'+d+'s;--s:'+s+'"></i>').join('');}

function infinityPendingSave(){try{if(infinityPending.actions.length)sessionStorage.setItem('yuro-tower-pending',JSON.stringify(infinityPending));else sessionStorage.removeItem('yuro-tower-pending');}catch{}}

function nextBattleLevel(b){const all=b.mode==='raid'?raidLevels.filter(l=>l.raidWorld===battleLevel(b)?.raidWorld):storyLevels,index=all.findIndex(l=>l.id===b.level);return index<0?null:all[index+1]||null;}

function hideReview(on){const d=dlg();if(!d)return;for(const n of d.children){if(n.classList.contains('psh')||n.classList.contains('dialog-close'))continue;if(on)n.inert=true;else if(n.inert)n.inert=false;}}

function castTitan(actor){actor.titan=true;actor.titanUsed=true;actor.titanTurns=4;actor.titanFresh=true;actor.cooldown=1;const add=Math.round(actor.maxHp*.5);actor.maxHp+=add;actor.hp+=add;return {hp:add};}

function yuroSaveSeedKey(c){return c.catalogKey?'key:'+c.catalogKey:Number.isInteger(c.anilistCharacterId)?'anilist:'+c.anilistCharacterId+'|'+c.series:'name:'+String(c.name||'').toLowerCase()+'|'+c.series;}

function yf3L(cls,body,defs){return '<i class="yf3-l '+cls+'" aria-hidden="true"><svg viewBox="-100 -100 200 200" focusable="false" aria-hidden="true">'+(defs?'<defs>'+defs+'</defs>':'')+body+'</svg></i>';}

function transcendentCardKey(c){return c.catalogKey?'key:'+c.catalogKey:Number.isInteger(c.anilistCharacterId)?'anilist:'+c.anilistCharacterId+'|'+c.series:'name:'+String(c.name||'').trim()+'|'+c.series;}

function recordBigPulls(){
 if(typeof cloudIsLive==='function'&&cloudIsLive()&&Date.now()-(globalThis.yuroFeedAt||0)>20000){globalThis.yuroFeedAt=Date.now();setTimeout(()=>void refreshPullFeed(),1500);}}

function raidEnemyPlan(level){const plan=raidEnemyPlanRaw(level);if(level?.manual)return plan;return balanceCampaignPlan(level?.enemies?.length?plan:distributeCampaignStats(plan,level,true),level,true);}

function stroke(t){if(t<0)return 0;if(t<NF*CYC){const u=t/CYC%1;return u<.4?ease(u/.4):1-ease((u-.4)/.6);}const e=ease(clamp((t-NF*CYC)/SETTLE));return HOLDP*e+Math.sin((t-NF*CYC)/1000/k*2.4)*.03*e;}

function getBoosterDefinition(id='multivers'){return packs.find(pack=>pack.id===id)||(developerMode&&typeof developerSecretPack!=='undefined'&&developerSecretPack.id===id?developerSecretPack:null);}

function releasedCatalogBaseline(seed){const base={};for(const field of releasedCatalogFields)if(seed[field]!==undefined)base[field]=field==='combatStats'?{...seed[field]}:seed[field];return base;}

function validCardVideo(value){if(typeof value!=='string'||value.length>1500)return false;try{const u=new URL(value);return u.protocol==='https:'&&!u.username&&!u.password;}catch{return false;}}

function stopAudio(){clearInterval(ui.timer);ui.timer=0;ui.deadline=0;ui.paused=0;ui.playId=(ui.playId||0)+1;if(player){try{player.pause();}catch{}}ui.audio=null;ui.silImg=null;ui.silStep=-1;}

function personalPullAge(at,now){const minutes=Math.max(0,Math.floor((now-at)/60000));return minutes<1?'À l’instant':minutes<60?'Il y a '+minutes+' min':'Il y a '+Math.floor(minutes/60)+' h';}

function yf3Star(x,y,r,c){return '<path d="M'+x+','+(y-r)+'Q'+x+','+y+' '+(x+r)+','+y+'Q'+x+','+y+' '+x+','+(y+r)+'Q'+x+','+y+' '+(x-r)+','+y+'Q'+x+','+y+' '+x+','+(y-r)+'Z" fill="'+c+'"/>';}

function anilistImage(url){return typeof url==='string'&&(/^https:\/\/s[0-9]+\.anilist\.co\//.test(url)||/^https:\/\/yuro-rho\.vercel\.app\/card-art\/[a-f0-9]{16}\.webp$/.test(url))?url:'';}

function ready(){requestAnimationFrame(()=>requestAnimationFrame(()=>{delete root.dataset.yuroBoot;root.removeAttribute('aria-busy');__R.getElementById('yuroStartup')?.remove();}));}

function storySkillCardOf(active){const card=active?.name?active:cardById(active?.cardId);return active?.alter&&card?{...card,name:active.alter.name,rarity:active.alter.rarity}:card;}

function clearRarityEmblemIntro(){const r=rarityEmblemRun;if(!r)return;rarityEmblemRun=null;clearTimeout(r.timer);r.scene.remove();r.button.classList.remove('rarity-emblem-waiting');}

function countCardGroups(list){const m=new Map();for(const c of list){const g=m.get(c.rarity)||{total:0,owned:0};g.total++;if(state.qty[c.id]>0)g.owned++;m.set(c.rarity,g);}return m;}

function unlockAudio(){try{if(!player){player=new Audio();player.preload='auto';}player.volume=volume;player.src=SILENCE;const p=player.play();if(p&&p.catch)p.catch(()=>{});}catch{}}

function offers(){const list=boosterOffers().filter(p=>p&&p.id!=='halloween'&&(!p.devOnly||localDev()));return list.length?list:[getBoosterDefinition('multivers')].filter(Boolean);}

function setStatText(id,v,html=false){const el=$(id);if(!el)return;const s=String(v);if(html){if(el.innerHTML!==s)el.innerHTML=s;}else if(el.textContent!==s)el.textContent=s;}

function buzz(pattern){if(!canVibrate()||!vibrationsOn()||!soundOn()||document.hidden)return false;try{return navigator.vibrate(pattern.slice())!==false;}catch{return false;}}

function burst(s,kind,make){const list=[...s.el.querySelectorAll('.psh-fx>.psh-'+kind)];list.forEach((e,i)=>{const [kf,o]=make(i,e);e.animate?.(kf,{fill:'forwards',...o});});}

function rng(seed){let s=seed>>>0;return()=>{s=(s+0x6D2B79F5)>>>0;let t=s;t=Math.imul(t^(t>>>15),t|1);t^=t+Math.imul(t^(t>>>7),t|61);return((t^(t>>>14))>>>0)/4294967296;};}

function storyOpponent(level){const pool=storyWorldCards(level.worldId);return pool.find(c=>level.portrait.test(c.name))||pool[Math.min(level.act-1,pool.length-1)]||null;}

function resetStoryPlayback(){stopStoryAuto();clearTimeout(storyAnimationTimer);storyPending=null;storyAnimating=false;storyEntering=false;storyImpact=null;storyFlash='';}

function freeBoosterTime(ms){const seconds=Math.max(0,Math.ceil(ms/1000));return String(Math.floor(seconds/60)).padStart(2,'0')+':'+String(seconds%60).padStart(2,'0');}

function raidEase(u,level){const p=raidPower(level);return u?{...u,hp:Math.max(1,Math.round((u.hp||1)*p.hp)),attack:Math.max(1,Math.round((u.attack||1)*p.attack))}:u;}

function cardRarityCode(rarity){const code=typeof rarityLabel==='function'?rarityLabel(rarity):String(rarity||'?').charAt(0);return String(code).length>3?'TRS':code;}

function yf3Bolt(r,a0,a1,j){let p='M'+yf3Pt(r,a0);const n=Math.round((a1-a0)/7);for(let i=1;i<=n;i++)p+='L'+yf3Pt(r+(i%2?j:-j)*(i===n?0:1),a0+(a1-a0)*i/n);return p;}

function transcendentNumbers(c){const v=state.transcendentEditions?.[transcendentCardKey(c)];return Array.isArray(v)?v.filter(n=>Number.isSafeInteger(n)&&n>0):[];}

function readPlayerProfile(){try{return normalizePlayerProfile(JSON.parse(localStorage.getItem(playerProfileKey()))||{});}catch{return normalizePlayerProfile();}}

function readStorage(key){try{const v=JSON.parse(localStorage.getItem(key));return typeof yuroLocalDecode==='function'?yuroLocalDecode(v):v}catch{return null}}

function serverPullAligned(data){return Object.entries(data.keys||{}).every(([id,key])=>serverCardIdentity((state.customCards||[])[Number(id)-65])===key);}

function evolutionKiReward(mode,levelId){const k=state.evolution?.settings.kiRewards[evolutionDropKey(mode,levelId)];return Number.isInteger(k)?k:null;}

function size(){if(!cv)return;dpr=Math.min(1,window.devicePixelRatio||1);cv.width=Math.round(innerWidth*dpr);cv.height=Math.round(innerHeight*dpr);}

function yf3Wave(r,amp,k){let p='';for(let i=0;i<=120;i++){const a=i*3,rr=r+amp*Math.sin(a*k*Math.PI/180);p+=(i?'L':'M')+yf3Pt(rr,a);}return p+'Z';}

function fill(out,vals){const by={'#':[],'*':[]};vals.forEach(([k,v])=>by[k].push(v));return out.replace(/[#*]/g,m=>by[m].length?by[m].shift():m);}

function today(){return new Intl.DateTimeFormat('en-CA',{timeZone:'Europe/Paris',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date())}

function storyTeamSlots(){return Array.from({length:3},(_,i)=>{const c=cardById(state.story.team[i]);return c&&state.qty[c.id]>0?c.id:null;});}

function techniqueSpeed(){return typeof storySpeed==='number'&&storySpeed>0&&typeof storyAnimating!=='undefined'&&storyAnimating?storySpeed:1;}

function cardArtSource(url){const m=/\/card-art\/([0-9a-z-]+)\.webp(?:\?.*)?$/i.exec(String(url||''));return m?'https://yurocollection.fr/card-art/'+m[1]+'.webp':url;}

function isRankedRoyalCard(c){return !!c&&(c.catalogKey===rankedRoyalCard.catalogKey||/^lamine?\s*yamal$/i.test(String(c.name||'').trim()));}

function cardThumb(url){const m=/\/card-art\/([0-9a-z-]+)\.webp(?:\?.*)?$/i.exec(String(url||''));return m?'https://yurocollection.fr/card-art/t/'+m[1]+'.webp':url;}

function startTimer(ms){ui.deadline=Date.now()+ms;ui.lastTick=0;clearInterval(ui.timer);ui.timer=setInterval(paintTimer,200);paintTimer();}

function shake(arena,k,ms=700){if(!arena)return;arena.classList.add('bc-shake');setTimeout(()=>arena.classList.remove('bc-shake'),ms*k);}

function duplicateSaleValue(scope=collectionScope()){return dupSaleCards(scope).reduce((n,c)=>n+dupSpare(c.id)*salePrices[c.rarity],0);}

function yuroFrameById(id){return typeof id==='string'?yuroFrames.find(f=>f.id===id)||yuroPrestigeFrames.find(f=>f.id===id)||null:null;}

function isCosmicGarou(c){return !!c&&(c.catalogKey===cosmicGarouKey||/garou/i.test(c.name||'')&&/cosmic|cosmique/i.test(c.name||''));}

function filteredAnimeIndexes(){return sortedAnimeIndexes(series.filter(s=>normalize(s.name).includes(normalize(animeIndexQuery))));}

function dupSpare(id){return typeof prestigeSpareCopies==='function'?prestigeSpareCopies(state,id):Math.max(0,(state.qty[id]||0)-1);}

function rimuruSelfCleanse(u){return !!u&&u.hp>0&&u.frozen>0&&!u.banished&&isRimuruName(u)&&u.cooldown===0&&!combatSpentSpecial(u);}

function legendStageHTML(){return '<div class="lg-stage" aria-hidden="true"><b class="lg-dim"></b><b class="lg-flash"></b></div>';}

function level(){try{return playerLevel(normalizePlayerProgress(state.playerProgress));}catch{return {level:1,current:0,next:1};}}

function place(el,R){el.style.left=R.left+'px';el.style.top=R.top+'px';el.style.width=R.width+'px';el.style.height=R.height+'px';}

function serverAuthorityPending(){return cloudIsLive()&&cloudIdentity()===authorityAccount?structuredClone(authorityCommands):[];}

function raidPower(level){const g=Math.max(0,raidLevels.findIndex(l=>l.id===level?.id));return {hp:.95+.045*g,attack:.92+.025*g};}

function frame(now){try{frameInner(now);}catch(e){console.error('[mv]',e&&e.stack||e);cv.remove();actor.style.visibility='';}}

function anim(s,el,kf,o){if(!el?.animate)return null;const a=el.animate(kf,{fill:'forwards',...o});s.anims.push(a);return a;}

function isCategorySeries(id,series){return isCategoryPack(id)&&categoryPackSeriesSets[id].has(String(series??'').trim());}

function seed(key){let n=2166136261;for(const c of String(key)){n^=c.charCodeAt(0);n=Math.imul(n,16777619);}return n>>>0;}

function storyWorldDisplayNumber(id){const index=storyWorlds.findIndex(w=>w.id===Number(id));return index<0?'—':index+1;}

function evolutionDropKey(mode,levelId){return (mode==='raid'?'raid':mode==='event'?'event':'story')+':'+levelId;}

function refreshTeamBuilder(){const y=window.scrollY;renderCombat();window.scrollTo({top:y,behavior:'instant'});}

function isHalloweenAlucard(c){return !!c&&String(c.name).trim().toLowerCase()==='alucard'&&c.rarity==='Secret';}

function yf3Pt(r,deg){const a=deg*Math.PI/180;return (r*Math.sin(a)).toFixed(1)+','+(-r*Math.cos(a)).toFixed(1);}

function storyAvailableTeam(){return state.story.team.map(cardById).filter(c=>c&&state.qty[c.id]>0).slice(0,3);}

function towerMilestoneKi(room){return Number.isInteger(room)&&room>0&&room%5===0?Math.min(2500,150+room*20):0;}

function setReopenLabel(text,aria){reopenBtn.textContent=text;reopenBtn.setAttribute('aria-label',aria||text);}

function stopAriseVoice(){try{ariseVoiceSource?.stop();}catch{}ariseVoiceSource=null;ariseVoiceAudio?.pause();}

function infinityPendingClear(){infinityPending.key='';infinityPending.actions=[];infinityPendingSave();}

function skip(){const s=sc;if(!s||s.done||s.leaving)return;s.skipped=true;sfx('card-slide');finish(s);}

function storyVisibleCleared(){return state.story.cleared.filter(id=>storyLevels.some(l=>l.id===id));}

function farmState(){if(!state.story.farm)state.story.farm=normalizeFarm();return state.story.farm;}

function evolutionItem(itemId){return state.evolution?.settings.items.find(i=>i.id===itemId)||null;}

function routeHash(){return view==='album'?'#index/'+encodeURIComponent(selectedSeries):'#'+view;}

function yf3Front(cls,[defs,body],more='',moreDefs=''){return yf3L(cls,body+more,defs+moreDefs);}

function mysteryRarity(card){return ['Mythique','Secret','Transcendant'].includes(card.rarity);}

function stopCardVideo(){__R.querySelectorAll('[data-card-video]').forEach(v=>v.pause());}

function geassRng(seed){let s=seed;return ()=>{s=(s*16807)%2147483647;return s/2147483647;};}

function isCategoryPack(id){return typeof id==='string'&&Object.hasOwn(CATEGORY_PACKS,id);}

function genjutsuSpeed(){return typeof storySpeed==='number'&&storySpeed>0?storySpeed:1;}

function vibrationsOn(){try{return localStorage.getItem(VKEY)!=='0';}catch{return true;}}

function tutorialData(){return normalizePlayerTutorial(state.playerProgress?.tutorial);}

function creatorRewardCard(){return cards.find(c=>c.catalogKey==='tiktok-white-obito');}

function beginPackReview(){packFlow.phase='review';packFlow.index=0;renderPackReview();}

function heavenSpeed(){return typeof storySpeed==='number'&&storySpeed>0?storySpeed:1;}

function speed(){return 1/(typeof storySpeed==='number'&&storySpeed>0?storySpeed:1);}

function storyWorldActCount(id){return storyLevels.filter(l=>l.worldId===id).length;}

function sunStageHTML(){return '<div class="sn-stage" aria-hidden="true"></div>';}

function farmPityLeft(f=farmState()){return Math.max(1,FARM_RATES.pity+1-f.pity);}

function combatEnemyCatalog(){return [...cards,...(state.story?.enemyCards||[])];}

function yf3Split(s){const i=s.indexOf('§');return [s.slice(0,i),s.slice(i+1)];}

function setVibrations(on){try{localStorage.setItem(VKEY,on?'1':'0');}catch{}}

function infinityPendingKey(d){return d?.season?.id+':'+(d?.me?.revision||0);}

function isIsekaiSeries(series){return isCategorySeries('isekai',series);}

function audio(){return typeof gameAudio==='function'?gameAudio():null;}

function isShojoSeries(series){return isCategorySeries('shojo',series);}

function stopStoryAuto(){storyAuto=false;clearTimeout(storyAutoTimer);}

function loopOff(s){if(s.loop)try{s.loop.stop();}catch{}s.loop=false;}

function activeBoosterPool(){return boosterPool(activeBooster().id);}

function team(){try{return storyAvailableTeam();}catch{return [];}}

function storyOwned(){return cards.filter(c=>state.qty[c.id]>0);}

function rarityLabel(rarity){return rarityCodes[rarity]||rarity;}

function ownedCards(){return cards.filter(owns);}

function keep(v,n){v.nodes.push(n);return n;}

