function infinityResultHTML(b){const won=b.result==='won';return `<section class="story-end-screen ${won?'won':'lost'}"><div class="story-result-rays" aria-hidden="true"></div><div class="story-end-panel"><div class="story-result-trophy" aria-hidden="true">${storyResultEmblem(won)}</div><h2 id="storyResultTitle">${won?'VICTOIRE':'DÉFAITE'}</h2><p class="combat-result-message">${won?'Une nouvelle porte s’ouvre. Poursuis ton ascension.':'Le château ne t’a pas vaincu pour toujours. Reviens plus fort.'}</p><span class="story-result-chapter">CHÂTEAU DE L’INFINI · CHAMBRE ${b.room}</span><div class="story-result-stars">${[1,2,3].map(n=>`<span class="${won&&n<=b.players.filter(u=>u.hp>0).length?'lit':''}">★</span>`).join('')}</div><div class="story-result-numbers"><div><strong>${b.players.filter(u=>u.hp>0).length}/${b.players.length}</strong><span>cartes debout</span></div><div><strong>${Math.max(1,b.turn-1)}</strong><span>tour${Math.max(1,b.turn-1)>1?'s':''}</span></div><div><strong>${Math.max(infinityUI.data?.me?.best||0,won&&Number.isInteger(b.room)?b.room:0)}</strong><span>record</span></div></div><div class="story-result-progress"><div><strong>${won?'Chambre conquise !':'Ton record reste acquis.'}</strong><small>${won&&b.rewardKi?'Palier atteint · +'+b.rewardKi+' ki':'Ton équipe récupère tous ses PV au prochain combat.'}</small></div></div><div class="story-result-buttons"><button class="btn primary" data-infinity-replay>↻ Rejouer</button><button class="btn ghost" data-infinity-start ${won?'':'disabled'}>Suivant →</button><button class="btn ghost" data-infinity-lobby>Retour au château</button></div></div></section>`;}

function infinityAfter(previous,next,i){const p=previous?.players?.[i],n=next?.players?.[i];if(!p)return null;if(n&&(!p.summon||n.summon===p.summon)&&(p.summon||!n.summon))return n;return next.players.find(u=>p.summon?u.summon===p.summon:(u.key===p.key&&!u.summon))||null;}

function infinityRefreshControls(){const auto=__R.querySelector('[data-infinity-autoplay]'),speed=__R.querySelector('[data-infinity-speed]');if(auto){auto.setAttribute('aria-pressed',String(infinityPlayback.auto));auto.textContent=infinityPlayback.auto?'Ⅱ Pause Auto':'▷ Auto Play';}if(speed){speed.classList.toggle('active',storySpeed===2);speed.setAttribute('aria-pressed',String(storySpeed===2));speed.innerHTML='×2 <small>'+(storySpeed===2?'ACTIVÉ':'VITESSE')+'</small>';}__R.querySelectorAll('[data-infinity-active]').forEach(button=>{const unit=infinityUI.data?.me?.battle?.players[Number(button.dataset.infinityActive)];button.disabled=infinityUI.busy||infinityPlayback.animating||infinityPlayback.auto||!unit||unit.hp<=0||unit.acted||!!infinityUI.data?.me?.battle?.result;});__R.querySelectorAll('[data-infinity-action]').forEach(button=>{const actor=infinityUI.data?.me?.battle?.players[infinityPlayback.active];button.disabled=infinityUI.busy||infinityPlayback.auto||!!infinityUI.data?.me?.battle?.result||(button.dataset.infinityAction==='skill'&&actor?.cooldown>0);});}

