 function aim(from,to){if(!from||!to)return;const a=fighterRects.get(from),b=fighterRects.get(to);if(!a||!b)return;from.style.setProperty('--strike-x',((b.left+b.width/2-a.left-a.width/2)*.82)+'px');from.style.setProperty('--strike-y',((b.top+b.height/2-a.top-a.height/2)*.82)+'px');}
